const cache =
new Map()

/*
|--------------------------------------------------------------------------
| SET
|--------------------------------------------------------------------------
*/

const set = (
  key,
  value
) => {

  cache.set(
    key,
    value
  )

}

/*
|--------------------------------------------------------------------------
| GET
|--------------------------------------------------------------------------
*/

const get = (
  key
) => {

  return cache.get(key)

}

/*
|--------------------------------------------------------------------------
| DELETE
|--------------------------------------------------------------------------
*/

const remove = (
  key
) => {

  cache.delete(key)

}

/*
|--------------------------------------------------------------------------
| CLEAR
|--------------------------------------------------------------------------
*/

const clear = () => {

  cache.clear()

}

module.exports = {

  set,

  get,

  remove,

  clear

}